// Arma el prompt del clasificador. El sobre viene de `Decidir` y ya trae la
// conversacion deduplicada.
const d = $('Decidir').first().json;
const conv = Array.isArray(d.conversation) ? d.conversation : [];
const ultimos = conv.slice(-6)
  .map((m) => (m.role === 'user' ? 'CLIENTE: ' : 'NOSOTROS: ') + String(m.content || ''))
  .join('\n');

return [{ json: {
  ...d,
  promptAgente: [
    'CONVERSACION RECIENTE:',
    ultimos || '(sin historial)',
    '',
    'ULTIMO MENSAJE DEL CLIENTE:',
    String(d.userMessage || ''),
  ].join('\n'),
} }];

// Normaliza la salida del Agente 1. Si el agente fallo (onError:continue) o
// devolvio algo que no matchea el schema, se cae a 'precio': es la rama con
// verificacion completa, asi que un error de clasificacion se degrada hacia la
// ruta MAS controlada, no hacia la mas suelta.
const d = $('Prompt Intención').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }

const VALIDAS = ['precio', 'info', 'producto', 'seguimiento', 'otro'];
let intencion = String(out.intencion || '').toLowerCase();
if (!VALIDAS.includes(intencion)) intencion = 'precio';

const confianza = Number(out.confianza);

// Confianza baja = tratarlo como pedido de precio (ruta verificada), no como info.
if (Number.isFinite(confianza) && confianza < 0.5 && intencion === 'info') intencion = 'precio';

return [{ json: {
  ...d,
  intencion,
  confianzaIntencion: Number.isFinite(confianza) ? confianza : 0,
  respuestaInfo: String(out.respuestaInfo || '').trim(),
  motivoIntencion: String(out.motivo || ''),
} }];

const d = $('Leer Intención').first().json;
const texto = String(d.respuestaInfo || '').trim();
return [{ json: { ...d, final: texto, accion: 'info', hayRespuesta: texto.length > 0 } }];

const d = $('Leer Intención').first().json;
const conv = Array.isArray(d.conversation) ? d.conversation : [];
const ultimos = conv.slice(-6)
  .map((m) => (m.role === 'user' ? 'CLIENTE: ' : 'NOSOTROS: ') + String(m.content || ''))
  .join('\n');
return [{ json: { ...d, promptAgente: [
  'CONVERSACION:', ultimos || '(sin historial)', '',
  'PEDIDO A RESOLVER:', String(d.userMessage || ''),
].join('\n') } }];

// Traduce la salida del Agente 2 al contrato que ya espera `Extraer Palabras`:
// { precio: { producto }, opciones: { productos } }.
const d = $('Prompt Selector').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }

const terminos = (Array.isArray(out.terminos) ? out.terminos : []).filter(Boolean).map(String);
const productos = (Array.isArray(out.productos) ? out.productos : []).filter(Boolean).map(String);

return [{ json: {
  ...d,
  seleccion: {
    terminos,
    productos,
    cantidad: Number.isFinite(Number(out.cantidad)) ? Number(out.cantidad) : null,
    necesitaAclaracion: !!out.necesitaAclaracion,
    pregunta: String(out.pregunta || ''),
  },
  // contrato que consume Extraer Palabras (heredado de v9)
  precio: { producto: terminos.join(' ') },
  opciones: { productos },
} }];

// Junta las filas de Buscar Candidatos (una por variante) en una lista cerrada
// y numerada, y guarda las filas CRUDAS enteras para el verificador final.
const d = $('Leer Selector').first().json;
const filas = $input.all().map((i) => i.json).filter((r) => r && r.producto_id);

const fmt = (n) => (n == null || !Number.isFinite(Number(n)))
  ? null
  : '$' + new Intl.NumberFormat('es-AR').format(Number(n));

// COMO SE COBRA: `unidad_venta` MANDA sobre `unidad`.
//
// Bug del 2026-07-29 (loop de reintento): "cuanto sale anillar 120 hojas" ->
// el bot dijo "$2.400 por hoja". Un anillado se cobra POR TRABAJO: los $2.400
// son el anillado entero. Si el cliente multiplica por 120 se lleva $288.000
// de una cotizacion de $2.400 (120x).
//
// La columna `unidad` del catalogo dice "Hoja" en 142 de 165 variantes, pero
// solo 48 se cobran de verdad por hoja. El dato bueno vive en
// atributos.unidad_venta: unidad(48) · hoja(40) · pack(26) · trabajo(18) ·
// m2 · metro. `unidad` es basura heredada de la carga; no se corrige en la
// base (es de TG) — se ignora cuando unidad_venta dice otra cosa.
//
// Esto NO lo pesco ningun test: el harness mockea filas donde las dos columnas
// coincidian. Lo encontro el verificador en produccion, rechazando dos veces
// seguidas — tenia razon las dos.
const COBRO = {
  trabajo: 'por trabajo',
  pack: null,       // el texto del pack lo arma porPack, que ya trae la cantidad
  unidad: 'por unidad',
  hoja: 'por hoja',
  pagina: 'por pagina',
  m2: 'por m2',
  metro: 'por metro',
};
// SIN FALLBACK A `unidad`. Medido sobre el catalogo real (2026-07-29): hay 6
// variantes sin unidad_venta, y en LAS SEIS `unidad` dice "Hoja" cuando en
// realidad son 3 anillados (por trabajo), Ojales (por unidad) y 2 Papel Vegetal
// (pack de 10). O sea: justo donde `unidad` es el unico dato disponible, miente.
// Caer a esa columna no rescata el caso — le pone una unidad incorrecta con
// cara de correcta, que es peor que no decir nada.
//
// Cuando no se sabe como se cobra, el precio NO se afirma: va a caveat (ver
// Calcular Montos). Los 5 anillados/vegetales ademas estan `oculto: true` y no
// llegan al cliente; el caso vivo es Ojales.
const comoSeCobra = (r) => {
  const uv = String(((r.atributos || {}).unidad_venta) || '').toLowerCase().trim();
  if (uv && Object.prototype.hasOwnProperty.call(COBRO, uv)) return { clave: uv, texto: COBRO[uv] };
  // `unidad` NO se usa como fallback a proposito. Se conserva el valor crudo solo
  // para poder diagnosticar desde el log cual fila vino sin unidad_venta.
  return { clave: null, texto: null, sinDato: true, unidadCruda: r.unidad || null };
};

// CUANTAS UNIDADES TRAE EL PACK.
//
// `por_pack` es un BOOLEANO (true/false), no la cantidad — pero se venia usando
// como si trajera el numero: 'el pack de ' + c.porPack daba "el pack de true".
// La cantidad real vive en atributos.pack_unidades (100 / 500 / 1000 / 2000).
// Misma clase de bug que `unidad`: el nombre del campo sugiere un dato que el
// campo no tiene.
const packDe = (r) => {
  const n = Number(((r.atributos || {}).pack_unidades));
  return Number.isFinite(n) && n > 0 ? n : null;
};

// LOS OTROS PACKS QUE EXISTEN. `pack_tiers` lista todos los tamanios de pack de
// ese producto ([100, 500, 1000]). El candidato es UNO solo, asi que sin esto el
// cliente que pregunta por tarjetas ve un solo pack y no sabe que hay otros.
const packsDisponibles = (r) => {
  const t = ((r.atributos || {}).pack_tiers);
  return Array.isArray(t) && t.length > 1 ? t.map(Number).filter(Number.isFinite) : null;
};

const lista = filas.map((r, i) => ({
  idx: i + 1,
  producto: r.nombre_canonico,
  variante: (r.variante && String(r.variante).trim()) || 'única',
  // `unidad` NO viaja en el candidato: el nombre promete la unidad de cobro y
  // trae otra cosa (dice "Hoja" en 142 de 165 variantes; solo 48 lo son). Si el
  // campo no existe, ningun nodo lo puede leer por error. El unico dato de
  // cobro es `cobro`, que sale de unidad_venta.
  unidadVenta: ((r.atributos || {}).unidad_venta) || null,
  cobro: comoSeCobra(r),
  precioLista: r.precio_lista,
  precioTexto: fmt(r.precio_lista),
  soloDescuentos: !!r.solo_descuentos,
  porPagina: !!r.por_pagina,
  // `por_pack` es el FLAG (booleano); `packDe` es la CANTIDAD (de pack_unidades)
  esPack: !!r.por_pack,
  porPack: packDe(r),
  packsDisponibles: packsDisponibles(r),
  // PEDIDO MINIMO. El precio SOLO vale a partir de esta cantidad. Hoy es un
  // producto (promo inmobiliarias: $15.000 el cartel llevando 6; suelto sale
  // $19.500). Ya estaba diagnosticado en v9 (preguntas-tg.md, promo
  // inmobiliarias): sin el minimo, "3 carteles" cotiza $45.000 contra $58.500
  // reales. v10 lo habia perdido.
  minUnidades: Number(((r.atributos || {}).min_unidades)) || null,
  // `multiplica` y `tecnologia` deciden si se puede dar un TOTAL (ver Calcular
  // Montos). Viajan crudos porque la regla los combina con la unidad de cobro.
  atributos: r.atributos || null,
  atributosProducto: r.atributos_producto || null,
  tieneReglas: !!r.tiene_reglas,
  // OJO CON `mostrable`: en la vista de v9 es `(not tiene_reglas)`, o sea
  // "el precio es un numero limpio, sin escalera por cantidad". NO es un flag
  // de visibilidad. Filtrar por el fue el bug del 2026-07-29: las impresiones
  // tienen rangos por cantidad -> tiene_reglas=true -> mostrable=false, asi
  // que los 29 candidatos correctos se filtraron y al agente le llego
  // "(la busqueda no devolvio nada)". El agente contesto bien sobre una lista
  // vacia; el que mentia era este nodo.
  precioLimpio: r.mostrable === true,
  rangos: Array.isArray(r.rangos_cantidad) ? r.rangos_cantidad : null,
  nicho: r.nicho || null,
  score: r.score,
}));

// TODOS los candidatos van al agente. La visibilidad real ya la resolvio el SQL
// (bot.taxonomia filtra los ocultos antes de llegar aca).
const texto = lista.map((c) => [
  '[' + c.idx + ']',
  c.producto,
  '| variante: ' + c.variante,
  c.precioTexto ? '| precio: ' + c.precioTexto + (c.cobro.texto ? ' ' + c.cobro.texto : '') : '| precio: no publicado',
  // el hueco se dice, no se disimula: sin unidad de cobro el precio no se afirma
  (c.precioTexto && c.cobro.sinDato && !c.porPagina && !c.esPack) ? '| (no consta como se cobra)' : '',
  c.porPagina ? '| se cobra por pagina' : '',
  c.porPack ? '| el precio es por un pack de ' + c.porPack + ' unidades' : (c.esPack ? '| se vende por pack' : ''),
  c.packsDisponibles ? '| tambien hay packs de ' + c.packsDisponibles.join(', ') : '',
  c.minUnidades ? '| ESTE PRECIO EXIGE LLEVAR AL MENOS ' + c.minUnidades : '',
  // NO dice "solo con descuento": el agente lo leia como "no se puede cotizar".
  // El precio SI se dice; el flag solo marca que puede haber una mejora.
  c.soloDescuentos ? '| el precio de lista es el TECHO (hay descuentos posibles)' : '',
].filter(Boolean).join(' ')).join('\n');

return [{ json: {
  ...d,
  candidatos: lista,
  // FILAS CRUDAS COMPLETAS: es lo que el verificador final tiene que ver.
  // No se recortan ni se resumen a proposito (decision de Martin 2026-07-29).
  filasCrudas: filas,
  nFilas: filas.length,
  promptAgente: [
    'PEDIDO DEL CLIENTE:',
    String(d.userMessage || ''),
    '',
    'CANDIDATOS DEL CATALOGO (lista cerrada, elegi por idx):',
    texto || '(la busqueda no devolvio nada)',
  ].join('\n'),
} }];

// UNICO PRODUCTOR DE MONTOS DEL FLUJO.
//
// Toma los candidatos que el Agente Relevancia eligio (por idx, contra la lista
// cerrada) y emite `hechos[]`: cada uno con el texto EXACTO que el compositor
// tiene permitido escribir. Si un monto no se puede afirmar con la informacion
// que hay, no se emite el hecho — se emite el caveat.
//
// Esta es la leccion de v8/v9 conservada: el LLM no ve las reglas de precio ni
// tipea montos. Los 4 confident-wrong del 27 y el 1,86x del 28 salieron todos de
// un LLM eligiendo un numero.
const d = $('Armar Candidatos').first().json;

// ¿YA SE LE AVISO AL CLIENTE QUE ESTE CANAL SOLO INFORMA?
//
// Se lee del nodo `Decidir` POR NOMBRE, no del sobre heredado: son 7 nodos de
// distancia y cualquiera que no propague la clave la convierte en undefined
// (=falso, o sea "primera vez"), que es como el mail termino tipeado dos veces en
// la misma conversacion el 2026-07-29.
//
// El try/catch NO es decorativo: si algun dia esta rama corriera sin que Decidir
// se haya ejecutado, $() tira "Referenced node doesn't exist" y mata el turno.
// Ante la duda se asume que NO se aviso — repetir el mail es molesto, callarlo
// deja al cliente sin saber como encargar.
let avisoYaDado = false;
try { avisoYaDado = $('Decidir').first().json.avisoDado === true; } catch (e) { avisoYaDado = false; }

// DESANIDADO ROBUSTO de la salida del agente.
//
// El nodo Agent con output parser no garantiza UNA forma: segun version y si
// returnIntermediateSteps esta prendido, `elegidos` puede venir en raw.output,
// raw.output.output, raw.data, como string JSON, o en la raiz. Buscar solo en
// tres lugares fijos hacia que una forma inesperada diera elegidos=[] — que es
// indistinguible de "el agente decidio que ninguno servia" y escala a mail sin
// dejar rastro. Se busca la CLAVE, no la ruta.
const desanidar = (raw, clave) => {
  const vistos = new Set();
  const pila = [raw];
  while (pila.length) {
    let n = pila.shift();
    if (typeof n === 'string') {
      const t = n.trim();
      if (t.startsWith('{') || t.startsWith('[')) { try { n = JSON.parse(t); } catch (e) { continue; } }
      else continue;
    }
    if (!n || typeof n !== 'object' || vistos.has(n)) continue;
    vistos.add(n);
    if (Array.isArray(n[clave])) return n;
    for (const k of ['output', 'data', 'json', 'result', 'response', 'text']) {
      if (n[k] !== undefined) pila.push(n[k]);
    }
  }
  return null;
};

const raw = $input.first().json;
const encontrado = desanidar(raw, 'elegidos');
const out = encontrado || {};
// Si NO se encontro la clave, el agente fallo de forma que no se puede
// interpretar. Eso NO es lo mismo que "no hay nada que decir": se marca para
// poder distinguir los dos casos en el log.
const salidaIlegible = !encontrado;

const candidatos = Array.isArray(d.candidatos) ? d.candidatos : [];
const porIdx = new Map(candidatos.map((c) => [Number(c.idx), c]));

const elegidosRaw = Array.isArray(out.elegidos) ? out.elegidos : [];

// GUARD: el agente solo puede nombrar idx que existan y sean mostrables.
let idxInvalidos = 0;
const elegidos = [];
for (const e of elegidosRaw) {
  const c = porIdx.get(Number(e.idx));
  // NO se filtra por `mostrable`: es `(not tiene_reglas)`, no un flag de
  // visibilidad (ver el comentario en Armar Candidatos). Solo se descarta un
  // idx que NO EXISTE en la lista cerrada.
  if (!c) { idxInvalidos++; continue; }
  // confianza ausente != confianza cero. Un agente que elige un producto y no
  // llena el campo esta diciendo "este es", no "no estoy seguro". Antes
  // `Number(undefined) || 0` daba 0 y el umbral lo descartaba: el turno moria
  // por un campo opcional que el LLM no lleno.
  const cf = Number(e.confianza);
  elegidos.push({
    ...c,
    confianza: Number.isFinite(cf) ? cf : 1,
    confianzaDeclarada: Number.isFinite(cf),
    porque: String(e.porque || ''),
  });
}

// UMBRAL BAJO A PROPOSITO (0.2, no 0.45).
//
// La confianza que emite un LLM no esta calibrada: 0.4 y 0.9 no significan lo
// mismo entre corridas ni entre modelos. Filtrar fuerte por ese numero es la
// misma clase de error que dejarlo tipear un precio — se le esta delegando una
// decision de negocio a un valor inventado.
//
// El umbral queda solo como red contra un candidato que el propio agente marca
// como malo (confianza muy baja). Quien decide de verdad si la respuesta sale
// es el VERIFICADOR, que ve el mensaje y las filas crudas. Mejor que el turno
// llegue al verificador y se rechace ahi con motivo, que morir mudo aca.
const UMBRAL = 0.2;
const confiables = elegidos.filter((c) => c.confianza >= UMBRAL);
const descartadosPorConfianza = elegidos.length - confiables.length;

const fmt = (n) => '$' + new Intl.NumberFormat('es-AR').format(Number(n));

// Construccion de hechos. Un hecho = un enunciado que el compositor puede decir.
// ═══ FLAGS DE PRECIO QUE SE IGNORAN A PROPOSITO (Martin, 2026-07-29) ═══
//
// db/precio-freshness.sql definio 4 reglas ademas de la escalera. Auditadas
// contra el catalogo real, Martin decidio:
//
//  · tiene_override → la spec decia "nunca mostrar numero (el empleado pisa el
//    precio)". SE IGNORA: se dice el precio de lista sin considerar el override.
//    Son 2 variantes (OPP Brillo $2.400, OPP Mate/Holografico/Kraft $2.500).
//
//  · precio_actualizado (frescura ≤30 dias) → REGLA ELIMINADA. Un precio viejo
//    igual se dice. Hoy no hay ninguno con mas de 30 dias.
//
//  · n_reglas_cantidad > 1 → la spec decia "ambiguo -> sin numero". SE IGNORA:
//    caso muy particular, hoy CERO variantes lo tienen.
//
// Esto queda escrito para que nadie los "arregle" mas adelante creyendo que
// faltan: la decision es no implementarlos.
const hechos = [];
const caveats = [];
for (const c of confiables) {
  const base = c.producto + (c.variante && c.variante !== 'única' ? ' (' + c.variante + ')' : '');

  // solo_descuentos ES TELEMETRIA, NO UNA ORDEN DE SILENCIO.
  //
  // Bug encontrado el 2026-07-29 ("papel kraft a4" -> "los precios de lista no
  // se publican"): este bloque cortaba el loop y mataba el precio. Toca 54
  // variantes en 21 productos — todos los folletos, todas las impresiones laser
  // color, los plastificados y las tarjetas. Las 54 TIENEN precio cargado
  // (ninguna en $0), asi que el bot tenia el dato y no lo decia.
  //
  // La definicion original esta en db/precio-freshness.sql (Increment B,
  // 2026-07-21) y dice textual:
  //   "solo_descuentos queda para telemetria (discount = signo negativo
  //    garantizado, precio_lista es TECHO)"
  // y en la tabla de clasificacion:
  //   "resto (discount/supercharge) -> numero de lista + caveat neutro"
  //
  // O sea: el precio se DICE. El flag solo marca que sobre ese producto hay
  // reglas de descuento, y como el descuento resta, precio_lista es el techo —
  // el cliente nunca paga mas que eso. Decirlo es seguro; callarlo manda a mail
  // a un cliente que ya tenia su respuesta.
  //
  // NO se calcula el descuento (decision de Martin 2026-07-29): el bot informa
  // el numero de lista y avisa que puede haber una mejora, sin intentar el
  // calculo. Los descuentos del kraft (por cantidad y por dorso) los cierra TG.
  if (c.soloDescuentos) {
    caveats.push({
      producto: base,
      nota: 'ese es el precio de lista; segun la cantidad puede haber un precio mejor, se consulta por mail',
    });
    // SIN continue: el precio sigue su curso normal y se emite como hecho.
  }
  // precio_lista == 0 NO significa "sin precio": hay variantes cuyo precio vive
  // solo en la escalera por cantidad (idx 5/6/7 del caso real: precio_lista 0
  // con rangos de $480 a $150). Solo es "sin precio" si tampoco hay rangos.
  const tieneRangos = Array.isArray(c.rangos) && c.rangos.some((x) => Number(x.value) > 0);
  if ((!Number.isFinite(Number(c.precioLista)) || Number(c.precioLista) <= 0) && !tieneRangos) {
    caveats.push({ producto: base, nota: 'no tiene precio cargado en el catalogo' });
    continue;
  }

  // PEDIDO MINIMO: el precio vale a partir de esa cantidad, pero la OFERTA se
  // dice igual.
  //
  // La promo inmobiliarias son $15.000 el cartel LLEVANDO 6; el cartel suelto
  // sale $19.500 (otra fila del catalogo, que llega como su propio candidato).
  //
  // ANTES ACA HABIA UN `continue` Y ESTABA MAL (Martin, 2026-07-29, ronda real).
  // El cliente dijo que era de una inmobiliaria y pidio 3 carteles: el suelto se
  // cotizo bien ($19.500) y la promo se descarto por no llegar al minimo, asi que
  // NUNCA se la ofrecio. Un vendedor diria las dos: "3 sueltos salen $19.500 cada
  // uno; llevando 6 te sale $15.000 cada uno". Es informacion verdadera y es la
  // razon de existir del producto.
  //
  // El razonamiento viejo confundia dos cosas distintas:
  //   · cotizar 3 A $15.000 seria mentir (1,3x por debajo) -> eso sigue prohibido:
  //     NO se emite total ni se presenta como el precio de lo que pidio.
  //   · nombrar la promo con su minimo NO es mentir -> es la oferta.
  //
  // Asi que en vez de descartar, se emite el hecho MARCADO como oferta
  // condicionada: sin total (el cliente no llega al minimo) y con el minimo
  // pegado al monto, de modo que el numero nunca viaje solo.
  const cantPedida = Number((d.seleccion || {}).cantidad);
  const bajoMinimo = !!(c.minUnidades && Number.isFinite(cantPedida)
    && cantPedida > 0 && cantPedida < c.minUnidades);

  // COMO SE COBRA. El orden importa: por_pagina y por_pack son flags explicitos
  // del producto y ganan. Despues manda `cobro`, que sale de unidad_venta.
  // NO hay fallback a la columna `unidad`: miente en 94 de 165 variantes, y en
  // las 6 donde seria el unico dato tambien miente (ver Armar Candidatos).
  // COLISION PACK + ESCALERA (rifas, 2026-07-29 en WhatsApp real).
  //
  // 'Talonarios Rifas 100 numeros' declara pack_unidades=100 (sale del NOMBRE)
  // y ADEMAS tiene escalera por cantidad, donde minQty es la cantidad de RIFAS
  // (100/250/500/1000/5000/10000). Pidiendo 500, el codigo elegia bien el tramo
  // ($10.000) pero seguia diciendo "el pack de 100 unidades" — dos cantidades
  // distintas en la misma frase, y la que el cliente lee es la equivocada.
  //
  // Cuando hay escalera, la cantidad que manda es la del TRAMO, no pack_unidades:
  // el pack fijo describe la unidad minima de venta, la escalera describe lo que
  // el cliente efectivamente pidio. Si se resolvio un tramo, el pack se calla.
  const tramoPisaPack = Array.isArray(c.rangos) && c.rangos.length > 0;

  const unidad = c.porPagina ? 'por pagina'
    // `porPack` ahora es la CANTIDAD (pack_unidades), no el booleano: antes esto
    // decia "el pack de true" porque leia `por_pack`, que es un flag.
    : (c.porPack && !tramoPisaPack) ? ('el pack de ' + c.porPack + ' unidades')
    : c.esPack ? 'el pack'
    : (c.cobro && c.cobro.texto) ? c.cobro.texto
    : null;

  // SIN UNIDAD DE COBRO NO SE AFIRMA EL PRECIO.
  //
  // Un monto suelto ("sale $500") lo lee cada cliente como quiere: por unidad,
  // por trabajo, por hoja. Ese hueco es justo el que produjo el 120x del
  // anillado. Antes esto se tapaba cayendo a `unidad`, que devolvia "por Hoja"
  // — incorrecto en las 6 filas donde pasa. Ahora va a caveat honesto.
  //
  // Solo aplica cuando NINGUNA fuente sabe: si hay por_pagina, pack o
  // unidad_venta, `unidad` ya quedo resuelta arriba.
  if (!unidad) {
    caveats.push({
      producto: base,
      nota: 'lo tenemos, pero te confirmamos por mail como se cobra para no pasarte un dato equivocado',
    });
    continue;
  }

  // Un precio POR TRABAJO no se multiplica por la cantidad. Si el cliente dijo
  // "120 hojas" y esto se cobra por trabajo, el monto ES el total: hay que
  // decirlo, porque si no el cliente multiplica solo.
  const esPorTrabajo = c.cobro && c.cobro.clave === 'trabajo';

  // ESCALERA POR CANTIDAD. `precio_lista` es el precio del PRIMER tramo (1-10),
  // no el que le corresponde al pedido. Para "200 paginas doble faz" el tramo
  // 51-250 vale $88 y precio_lista dice $150: informar precio_lista seria un
  // 1,7x — la misma clase de error que los confident-wrong del 27.
  //
  // El tramo se elige ACA, con la cantidad que el Selector ya extrajo, y de la
  // fila SQL. El LLM no ve las reglas ni elige el tramo.
  const cantidad = Number((d.seleccion || {}).cantidad);
  let monto = Number(c.precioLista);
  let tramo = null;
  if (Array.isArray(c.rangos) && c.rangos.length) {
    if (Number.isFinite(cantidad) && cantidad > 0) {
      const r = c.rangos.find((x) => {
        const min = Number(x.minQty) || 1;
        const max = x.maxQty == null ? Infinity : Number(x.maxQty);
        return cantidad >= min && cantidad <= max;
      });
      if (r && Number.isFinite(Number(r.value))) {
        monto = Number(r.value);
        tramo = { desde: r.minQty, hasta: r.maxQty, cantidad };
      }
    }
  }

  // ESCALERAS DE PUNTOS, NO DE RANGOS.
  //
  // Las rifas traen tramos {minQty:500, maxQty:501}: ventanas de UNA unidad, o
  // sea puntos de una lista de precios (100, 250, 500, 1000...), no rangos
  // continuos. Pidiendo 600 no cae en ninguno -> monto quedaba en 0 -> se
  // informaba el PISO ($6.000, el de 100 rifas) como si fuera el precio de 600.
  //
  // Cuando la cantidad cae ENTRE dos puntos, no se inventa: se dice el precio
  // del punto inmediatamente inferior aclarando a cuantas unidades corresponde,
  // y el cliente pregunta por el suyo. Un precio de otra cantidad presentado sin
  // aclaracion es la misma clase de error que el 120x del anillado.
  let escalon = null;
  if (!(monto > 0) && tieneRangos && Number.isFinite(cantidad) && cantidad > 0) {
    const puntos = c.rangos
      .map((x) => ({ q: Number(x.minQty) || 0, v: Number(x.value) }))
      .filter((x) => x.q > 0 && Number.isFinite(x.v) && x.v > 0)
      .sort((a, b) => a.q - b.q);
    const inferior = puntos.filter((x) => x.q <= cantidad).pop();
    if (inferior) { monto = inferior.v; escalon = inferior.q; }
  }

  // Si aun asi no hay monto (no se dijo cantidad, o pidio menos que el escalon
  // mas chico), se informa el PISO como "desde", que es un dato cierto.
  if (!(monto > 0) && tieneRangos) {
    const piso = Math.min(...c.rangos.map((x) => Number(x.value)).filter((v) => Number.isFinite(v) && v > 0));
    if (Number.isFinite(piso)) { monto = piso; tramo = null; }
  }
  if (!(monto > 0)) {
    caveats.push({ producto: base, nota: 'el precio depende de la cantidad; lo confirmamos por mail' });
    continue;
  }

  // "(por 120 unidades)" solo tiene sentido si el precio ES por unidad. En un
  // precio por trabajo diria "$2.400 por trabajo (por 120 unidades)", que es
  // justo la lectura que hay que evitar.
  // La cantidad que se nombra sale del TRAMO (lo que el cliente pidio y cayo
  // exacto) o del ESCALON (el punto inferior de la lista, cuando pidio una
  // cantidad intermedia). En el segundo caso hay que decir que el precio es
  // POR ESA cantidad, no por la que pidio.
  const porTramo = esPorTrabajo ? ''
    : tramo ? ' (por ' + tramo.cantidad + ' unidades)'
    : escalon ? ' (precio por ' + escalon + ' unidades)'
    : '';

  // ═══ TOTAL (decision de Martin 2026-07-29) ═══
  //
  // Reemplaza la politica del 2026-07-28 ("NO se da el total: hay recargo UV y
  // el precio guardado es el base, multiplicar sub-cotizaria"). Se cotiza cerrado
  // SOLO donde no hay recargo posible; donde puede haberlo, sigue yendo el
  // unitario y el total se confirma por mail.
  //
  // TRES condiciones, y las tres tienen que darse:
  //
  //  1. NO es un producto UV. Son 2 en el catalogo (tecnologia='uv'): 'Vinilo,
  //     Lona Brillo/Mate Uv' e 'Impresión Uv Holografico / Glitter'. Ahi el
  //     precio guardado es el BASE y el recargo lo pone el taller.
  //
  //  2. El catalogo dice que se multiplica (atributos.multiplica). Los packs
  //     traen multiplica:false — el precio ES el pack, multiplicarlo por las
  //     unidades del pack seria cobrarlo N veces.
  //
  //  3. LA CANTIDAD Y LA UNIDAD DE COBRO SON LA MISMA COSA. Esta es la que
  //     importa y no la resuelve ningun flag: 'anillar 120 hojas' tiene
  //     cantidad=120 y unidad_venta='trabajo' con multiplica=true — pero el
  //     ese true significa "3 anillados salen 3x", NO "x120 hojas". Multiplicar
  //     ahi es el mismo 120x que ya nos mordio, ahora del lado del total.
  //     Solo se multiplica cuando el cliente conto EN LA MISMA UNIDAD en que
  //     se cobra: hojas/paginas con precio por hoja, unidades con precio por
  //     unidad. Ante cualquier otra combinacion, no hay total.
  const uvPosible = String(((c.atributosProducto || {}).tecnologia)
    || ((c.atributos || {}).tecnologia) || '').toLowerCase() === 'uv';
  const multiplicable = ((c.atributos || {}).multiplica) === true;
  const claveCobro = (c.cobro && c.cobro.clave) || null;
  // que unidad conto el cliente, deducido de como se cobra el producto
  const cantidadEsLaUnidad = c.porPagina
    ? (claveCobro === 'hoja' || claveCobro === 'pagina' || claveCobro === null)
    : (claveCobro === 'hoja' || claveCobro === 'pagina' || claveCobro === 'unidad');

  let total = null;
  let motivoSinTotal = null;
  if (Number.isFinite(cantidad) && cantidad > 0) {
    if (uvPosible) motivoSinTotal = 'uv';
    else if (!multiplicable) motivoSinTotal = 'no_multiplica';
    else if (!cantidadEsLaUnidad) motivoSinTotal = 'unidad_distinta';
    else if (escalon) motivoSinTotal = 'cantidad_intermedia';  // el precio ya es de otra cantidad
    // BAJO EL MINIMO NO HAY TOTAL. El monto es de la promo, la cantidad es la que
    // el cliente pidio: multiplicarlos cotizaria 3 x $15.000 = $45.000 cuando lo
    // real son $58.500. Es el 1,3x que el `continue` viejo evitaba — se sigue
    // evitando, pero sin tirar la oferta a la basura.
    else if (bajoMinimo) motivoSinTotal = 'bajo_minimo';
    else total = monto * cantidad;
  }

  hechos.push({
    producto: base,
    // el total va como campo aparte: el compositor NO lo calcula, lo copia.
    total,
    totalTexto: total ? fmt(total) + ' por ' + cantidad + ' unidades' : null,
    cantidadPedida: Number.isFinite(cantidad) && cantidad > 0 ? cantidad : null,
    motivoSinTotal,
    // EL MINIMO VIAJA PEGADO AL MONTO, no como aclaracion aparte.
    //
    // Un caveat es una linea suelta que el compositor puede resumir, mover o
    // perder — y el verificador la borro entera creyendola relleno. Dentro de
    // `texto` es intocable: el compositor copia ese string caracter por caracter
    // (es su regla mas fuerte) y el guard de plata compara el monto ahi mismo.
    // Asi el numero de la promo NUNCA aparece sin la condicion que lo habilita.
    texto: fmt(monto) + (unidad ? ' ' + unidad : '') + porTramo
      + (c.minUnidades ? ' llevando ' + c.minUnidades + ' o mas' : ''),
    // marca de OFERTA CONDICIONADA: el cliente pidio menos que el minimo, asi que
    // esto es un "te conviene si llevas mas", no el precio de lo que pidio.
    ofertaBajoMinimo: bajoMinimo,
    minUnidades: c.minUnidades || null,
    monto,
    tramo,
    // se propaga para que el compositor sepa que ese numero NO se multiplica
    esPorTrabajo,
    comoSeCobra: (c.cobro && c.cobro.clave) || null,
    // el punto de la escalera que se uso cuando la cantidad cayo entre dos
    escalon,
    // el piso de la escalera, para que el compositor pueda decir "desde"
    desde: Array.isArray(c.rangos) && c.rangos.length
      ? Math.min(...c.rangos.map((x) => Number(x.value)).filter(Number.isFinite))
      : null,
    confianza: c.confianza,
    // NO se calcula el TOTAL aunque haya cantidad: hay recargo UV y el unitario
    // es el BASE (decision v9.2, 2026-07-28). El total lo confirma un humano.
    tieneReglas: !!c.tieneReglas,
  });

  // OTROS TAMANIOS DE PACK. El candidato es UN pack ("100 Tarjetas"), pero
  // pack_tiers dice que existen [100, 500, 1000]. Sin esto el cliente que pide
  // 500 tarjetas ve el precio del pack de 100 y no se entera de que hay uno que
  // le sirve mejor. Va como caveat (texto), no como monto: los precios de los
  // otros packs son OTRAS filas del catalogo y no estan autorizados aca.
  // EL MINIMO YA NO VA POR ACA: viaja dentro de `texto` (ver arriba), pegado al
  // monto. Como caveat era una linea aparte que el verificador podia borrar
  // creyendola relleno — y lo hizo. Duplicarlo aca ademas hacia que el compositor
  // dijera la condicion dos veces en el mismo mensaje.

  if (c.packsDisponibles && c.porPack) {
    const otros = c.packsDisponibles.filter((n) => n !== c.porPack);
    if (otros.length) {
      caveats.push({
        producto: base,
        nota: 'tambien se hace en packs de ' + otros.join(', ') + ' (otro precio, se consulta aparte)',
      });
    }
  }
}

// Los montos autorizados: el verificador chequea contra ESTA lista.
// Los TOTALES tambien van: el cliente los va a leer, asi que tienen que pasar
// el mismo guard que los unitarios. Sin esto el compositor escribe un total
// legitimo y el chequeo lo marca como inventado.
const montosAutorizados = hechos
  .flatMap((h) => [h.monto, h.total])
  .filter((n) => Number.isFinite(n) && n > 0);

const hayAlgoQueDecir = hechos.length > 0 || caveats.length > 0;

// POR QUE NO HAY NADA QUE DECIR. Sin esto, el turno escala y no queda registro
// de cual de las cuatro causas fue — que es exactamente lo que paso el
// 2026-07-29 con "200 paginas doble faz en obra 75": la busqueda traia los
// productos correctos y el turno murio igual, sin forma de saber por que.
let motivoVacio = null;
if (!hayAlgoQueDecir) {
  if (salidaIlegible) motivoVacio = 'salida_ilegible';                      // el agente devolvio algo no interpretable
  else if (!candidatos.length) motivoVacio = 'busqueda_vacia';              // el SQL no trajo filas
  else if (!elegidosRaw.length) motivoVacio = 'agente_no_eligio';           // el agente devolvio lista vacia
  else if (!elegidos.length) motivoVacio = 'idx_invalidos';                 // eligio idx que no existen
  else if (!confiables.length) motivoVacio = 'confianza_baja';              // todos por debajo del umbral
  else motivoVacio = 'sin_precio_publicable';                               // eligio, pero ninguno tiene precio
}

return [{ json: {
  ...d,
  hechos,
  caveats,
  montosAutorizados,
  elegidos: confiables,
  idxInvalidos,
  salidaIlegible,
  descartadosPorConfianza,
  motivoVacio,
  // se guarda la salida cruda del agente cuando no se pudo interpretar: es el
  // unico material para diagnosticar sin volver a mirar las ejecuciones a mano
  crudoAgente: salidaIlegible ? JSON.stringify(raw).slice(0, 800) : null,
  dudaNicho: !!out.dudaNicho,
  motivoRelevancia: String(out.motivo || ''),
  hayAlgoQueDecir,
  // el compositor recibe HECHOS, no prosa (decision v9.2)
  promptAgente: [
    'PEDIDO DEL CLIENTE:',
    String(d.userMessage || ''),
    '',
    'HECHOS AUTORIZADOS (copiá los montos EXACTO, no calcules nada):',
    hechos.length
      ? hechos.map((h) => '- ' + h.producto + ': ' + h.texto
          // El TOTAL ya viene calculado. El compositor lo COPIA, no lo saca:
          // multiplicar es justo lo que no puede hacer.
          + (h.totalTexto ? '\n    TOTAL YA CALCULADO: ' + h.totalTexto : '')).join('\n')
      : '(ninguno)',
    // POR QUE NO HAY TOTAL, cuando el cliente dio una cantidad. Sin esto el
    // compositor improvisa una razon (fue el bug de "hay recargos" del 29).
    hechos.some((h) => h.motivoSinTotal) ? '' : null,
    hechos.some((h) => h.motivoSinTotal) ? 'SOBRE EL TOTAL DE ESTOS:' : null,
    hechos.filter((h) => h.motivoSinTotal).map((h) => {
      const m = h.motivoSinTotal;
      return '- ' + h.producto + ': '
        + (m === 'uv' ? 'lleva impresion UV y el precio final depende del trabajo; deci que el total se confirma por mail.'
        : m === 'no_multiplica' ? 'el precio ya es por el pack completo, no se multiplica.'
        : m === 'unidad_distinta' ? 'la cantidad que dijo el cliente NO son unidades de este producto; deci el precio unitario y que el total se confirma por mail.'
        : m === 'bajo_minimo' ? 'es una OFERTA que arranca en ' + h.minUnidades
          + ' unidades y el cliente pidio menos. NO calcules el total ni la presentes'
          + ' como el precio de lo que pidio: ofrecela como alternativa que le conviene'
          + ' si lleva ' + h.minUnidades + ' o mas.'
        : 'el precio corresponde a otra cantidad; deci el total se confirma por mail.');
    }).join('\n') || null,
    // OFERTA POR CANTIDAD (promo inmobiliarias, 2026-07-29).
    //
    // El cliente pidio menos que el minimo y hay un precio mejor esperandolo mas
    // arriba. Sin esta instruccion el compositor trata la oferta como un estorbo
    // (no encaja con lo que pidieron) y la omite — que es medio bug: el otro medio
    // fue el verificador borrandola.
    hechos.some((h) => h.ofertaBajoMinimo) ? '' : null,
    hechos.some((h) => h.ofertaBajoMinimo)
      ? 'DECI LAS DOS COSAS: el precio de lo que el cliente pidio Y la oferta por'
      : null,
    hechos.some((h) => h.ofertaBajoMinimo)
      ? 'cantidad. El cliente tiene que poder comparar y decidir si le sirve llevar'
      : null,
    hechos.some((h) => h.ofertaBajoMinimo)
      ? 'mas. Callarse la oferta le esconde un precio mejor: eso no se hace.'
      : null,
    caveats.length ? '' : null,
    caveats.length ? 'ACLARACIONES QUE TENES QUE DECIR:' : null,
    caveats.length ? caveats.map((c) => '- ' + c.producto + ': ' + c.nota).join('\n') : null,
    // PRECIO POR TRABAJO CON CANTIDAD A LA VISTA. Sin decirlo, el cliente que
    // pregunto "anillar 120 hojas" lee "$2.400" y multiplica por 120 (120x).
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad ? '' : null,
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad
      ? 'IMPORTANTE: los montos marcados "por trabajo" son el precio del trabajo COMPLETO,'
      : null,
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad
      ? 'no por cada una de las ' + (d.seleccion || {}).cantidad + ' unidades. Decilo explicito para que el'
      : null,
    hechos.some((h) => h.esPorTrabajo) && (d.seleccion || {}).cantidad
      ? 'cliente no multiplique por su cuenta.'
      : null,
    '',
    'Cada hecho dice COMO se cobra (por trabajo, por unidad, por hoja, por m2...).',
    'Respetalo tal cual: cambiar la unidad cambia el precio aunque el numero sea el mismo.',
    '',
    // ANTES ESTA LINEA DECIA "(hay recargos que dependen del trabajo)".
    // El compositor la copiaba al mensaje real y le explicaba al cliente una
    // causa que nadie le dio — la razon del recargo es interna, no es un hecho
    // autorizado. Visto en la ronda del 2026-07-29: "ya que depende de otros
    // factores del trabajo" aparecio en 5 mensajes distintos.
    'Si un hecho NO trae "TOTAL YA CALCULADO" y el cliente pidio una cantidad:',
    'NO lo multiplices vos. Deci el precio unitario y, si arriba hay una razon en',
    '"SOBRE EL TOTAL", usa esa. Nunca inventes otra.',
    '',
    // AVISO DE CANAL: UNA sola vez por conversacion, en el primer mensaje que
    // lleva precio (decision de Martin 2026-07-29). Repetirlo en cada turno es
    // ruido pago; no decirlo nunca deja al cliente sin saber como encargar.
    //
    // SE LEE DE $('Decidir') DIRECTO, NO DEL SOBRE (`d.avisoDado`).
    //
    // Bug encontrado el 2026-07-29 (el mail dos veces en la misma conversacion):
    // `Decidir` calcula el flag bien (busca el mail del negocio en los salientes
    // del bot), pero entre Decidir y este nodo hay SIETE nodos que rearman el
    // sobre, y basta que uno no propague la clave para que llegue undefined —
    // que es falso, o sea "primera vez", siempre. Leyendo el nodo por nombre el
    // dato no puede diluirse en la cadena.
    avisoYaDado
      ? 'NO repitas que el canal es informativo ni el mail: ya se lo dijiste antes'
      : null,
    avisoYaDado
      ? 'en esta conversacion. Repetirlo en cada mensaje es molesto.'
      : null,
    hechos.length && !avisoYaDado
      ? 'CERRA CON EL CANAL (es la primera vez que le pasas un precio): una linea corta'
      : null,
    hechos.length && !avisoYaDado
      ? 'diciendo que por acá informamos y que el pedido se hace por mail a'
      : null,
    hechos.length && !avisoYaDado
      ? 'terminalgrafica@gmail.com o en el local. Una sola vez, sin insistir.'
      : null,
  ].filter((l) => l !== null).join('\n'),
} }];

const d = $('Calcular Montos').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }

const mensaje = String(out.mensaje || '').trim();

// QUE VUELTA ES. El contador NO puede vivir en el sobre: `d` sale de
// $('Calcular Montos'), que corre UNA sola vez, asi que en el reintento
// devolveria el mismo valor de siempre y el loop no terminaria nunca.
// $runIndex del compositor lo lleva n8n: 0 la primera pasada, 1 la segunda.
let intento = 1;
try { intento = Number($runIndex) + 1; } catch (e) { intento = 1; }
if (!Number.isFinite(intento) || intento < 1) intento = 1;

return [{ json: {
  ...d,
  borrador: mensaje,
  huboCompositor: mensaje.length > 0,
  intento,
  // se arrastra el feedback de la vuelta anterior para poder loguearlo aunque
  // el segundo intento salga aprobado (queremos saber que hubo que corregir)
  feedbackPrevio: String(d.feedbackPrevio || ''),
} }];

// El verificador ve TODO (decision de Martin 2026-07-29): el mensaje, el pedido,
// los hechos autorizados y EL RESULTADO CRUDO COMPLETO de la consulta SQL —
// incluidas las filas que el selector descarto. Sin eso no puede detectar
// "elegiste el producto equivocado", que es la clase de error mas cara.
const d = $('Leer Compositor').first().json;
const conv = Array.isArray(d.conversation) ? d.conversation : [];
const dialogo = conv.slice(-8)
  .map((m) => (m.role === 'user' ? 'CLIENTE: ' : 'NOSOTROS: ') + String(m.content || ''))
  .join('\n');

// GUARD DETERMINISTICO PREVIO: extrae los numeros del borrador y los compara
// contra los montos autorizados. El agente igual audita, pero esto ya deja el
// dato crudo servido y no depende de que el LLM sepa comparar numeros.
const enTexto = (String(d.borrador || '').match(/\$\s?[\d.]+/g) || [])
  .map((s) => Number(s.replace(/[^\d]/g, '')))
  .filter((n) => Number.isFinite(n) && n > 0);
const autorizados = new Set((d.montosAutorizados || []).map(Number));
const noAutorizados = enTexto.filter((n) => !autorizados.has(n));

// LAS FILAS CRUDAS TIENEN QUE MOSTRAR LA ESCALERA.
//
// Bug del 2026-07-29 (2do rechazo): se mostraba solo `precio_lista` y el
// verificador leia "hechos dicen $88" contra "la base dice 150" -> concluia
// PRECIO INVENTADO, correctamente para la informacion que le estabamos dando.
// El $88 sale de `rangos_cantidad` (tramo 51-250), que no aparecia en el
// prompt. Mostrar la mitad de la evidencia es peor que no mostrarla: el
// auditor rechaza lo que esta bien.
const escalera = (r) => {
  const rs = Array.isArray(r.rangos_cantidad) ? r.rangos_cantidad : null;
  if (!rs || !rs.length) return '';
  return ' | escalera por cantidad: ' + rs.map((x) => {
    const hasta = x.maxQty == null ? '+' : '-' + x.maxQty;
    return (x.minQty || 1) + hasta + ': $' + x.value;
  }).join(', ');
};

const crudas = (d.filasCrudas || []).map((r, i) => [
  '  fila ' + (i + 1) + ':',
  r.nombre_canonico,
  '| variante: ' + (r.variante || 'única'),
  // `precio_lista` es el precio del PRIMER tramo, no "el precio". Se nombra asi
  // para que el auditor no lo lea como el unico valor valido.
  '| precio base (tramo 1): ' + r.precio_lista,
  escalera(r),
  // COMO SE COBRA, no la columna `unidad`.
  //
  // Bug del 2026-07-29 (loop de reintento): el anillado tiene unidad="Hoja"
  // pero unidad_venta="trabajo". Mostrandole "unidad: Hoja" al auditor, este
  // rechazo "por hoja" (sabe que un anillado no se cobra asi), el compositor
  // lo saco, y entonces rechazo por sacarlo citando "los hechos dicen por
  // Hoja". Dos veredictos opuestos, los dos correctos para la evidencia que
  // le daba. La contradiccion estaba en el dato, no en el LLM.
  // Aca `unidad` SI se muestra, pero etiquetada como no confiable: el auditor
  // esta diagnosticando, no cotizando, y saber que la columna dice "Hoja"
  // mientras no hay unidad_venta es exactamente lo que necesita para entender
  // por que el mensaje no afirma como se cobra.
  '| se cobra: ' + (((r.atributos || {}).unidad_venta)
    || ('SIN DATO (la columna unidad dice ' + (r.unidad || '-') + ', pero NO es confiable: dice "Hoja" en 142 de 165 variantes)')),
  // el pack: `por_pack` es un booleano, la cantidad esta en pack_unidades
  ((r.atributos || {}).pack_unidades) ? '| pack de ' + (r.atributos.pack_unidades) + ' unidades' : '',
  // el minimo condiciona el precio: sin esto el auditor no puede detectar que se
  // cotizo por debajo del pedido minimo
  ((r.atributos || {}).min_unidades) ? '| MINIMO ' + (r.atributos.min_unidades) + ' unidades' : '',
  // Etiquetado para el auditor: sin esto lee "solo_descuentos: true" y concluye
  // que el precio no se podia decir — que es justo el bug que se arreglo.
  r.solo_descuentos ? '| hay descuentos posibles (el precio de lista es el TECHO, decirlo es correcto)' : '',
  '| score: ' + r.score,
].filter(Boolean).join(' ')).join('\n');

return [{ json: {
  ...d,
  numerosNoAutorizados: noAutorizados,
  promptAgente: [
    'MENSAJE QUE ESTA POR SALIR:',
    '"""', String(d.borrador || ''), '"""',
    '',
    'CONVERSACION CON EL CLIENTE:',
    dialogo,
    '',
    'HECHOS AUTORIZADOS (los unicos montos que se pueden decir):',
    (d.hechos || []).map((h) => '- ' + h.producto + ': ' + h.texto
      // El total lo calculo el CODIGO, no el compositor. Sin mostrarlo aca el
      // auditor ve un numero grande que no esta en la lista y lo tumba.
      + (h.totalTexto ? ' | TOTAL AUTORIZADO: ' + h.totalTexto : '')
      // OFERTA MARCADA EXPLICITA. Sin esto el auditor ve un precio que no encaja
      // con la cantidad pedida y lo lee como ruido — fue lo que paso el 29 con la
      // promo de inmobiliarias.
      + (h.ofertaBajoMinimo ? ' | OFERTA POR CANTIDAD: NO LA BORRES (arranca en '
        + h.minUnidades + ' unidades; el cliente pidio menos, pero tiene derecho a saberlo)' : '')
    ).join('\n') || '(ninguno)',
    (d.hechos || []).some((h) => h.totalTexto)
      ? 'Los TOTALES los calculo el codigo (precio x cantidad), no el compositor: son validos.'
      : '',
    '',
    'RESULTADO CRUDO COMPLETO DE LA BASE (' + (d.filasCrudas || []).length + ' filas, incluidas las descartadas):',
    crudas || '(sin filas)',
    '',
    'COMO SE CALCULARON LOS HECHOS (leelo antes de juzgar un monto):',
    (d.seleccion || {}).cantidad
      ? 'El cliente pidio ' + (d.seleccion || {}).cantidad + ' unidades.'
      : 'El cliente no dijo una cantidad concreta.',
    'Cuando un producto tiene ESCALERA POR CANTIDAD, el monto autorizado es el del',
    'TRAMO que corresponde a esa cantidad — NO el "precio base (tramo 1)".',
    'Que un monto no coincida con el precio base NO significa que este inventado:',
    'buscalo en la escalera de esa fila antes de rechazar.',
    '',
    'SI UNA FILA DICE "hay descuentos posibles": el precio de lista IGUAL se dice.',
    'Ese flag marca que el monto es el TECHO (los descuentos restan), no que sea',
    'secreto. NO rechaces un mensaje por decir el precio de un producto con',
    'descuentos, y NO exijas que lo derive a mail.',
    '',
    'LA UNIDAD DE COBRO sale del campo "se cobra" de cada fila (por trabajo, por',
    'unidad, por hoja, por m2...). Ese es el dato bueno. Los hechos autorizados ya',
    'lo respetan. NO juzgues la unidad por el nombre del producto ni por lo que te',
    'parezca razonable: si "se cobra: trabajo", el mensaje tiene que decir que es',
    'por el trabajo completo, y eso es CORRECTO aunque suene raro.',
    '',
    noAutorizados.length
      ? 'ALERTA AUTOMATICA: el mensaje contiene montos que NO estan autorizados: ' + noAutorizados.join(', ')
      : 'CHEQUEO AUTOMATICO DE MONTOS: OK — todos los montos del mensaje estan en la\n'
        + 'lista de hechos autorizados. Este chequeo es DETERMINISTICO (lo hace el codigo\n'
        + 'comparando numero por numero), asi que NO lo contradigas: si dice OK, ningun\n'
        + 'monto fue inventado.',
  ].join('\n'),
} }];

const d = $('Prompt Verificador').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }

// El guard deterministico MANDA sobre el agente: si hay un monto no autorizado
// en el texto, se rechaza aunque el verificador haya dicho que si. Un LLM no
// puede habilitar un numero que el calculo no produjo.
let montoInventado = (d.numerosNoAutorizados || []).length > 0;
const aprobadoLLM = out.aprobado === true;
let fallaLLM = String(out.falla || '');

// ═══ CORRECCION DEL VERIFICADOR (decision de Martin 2026-07-29) ═══
//
// El verificador puede devolver el mensaje ya arreglado en vez de solo rechazar.
// Sirve para lo que se cura sacando texto: ofrecer tomar un pedido, pedir un
// archivo, explicar por que falta un dato.
//
// EL PROBLEMA QUE ESTO ABRE, Y COMO SE TAPA: el verificador pasa a ser el unico
// que escribe SIN que nadie lo audite despues (es el ultimo eslabon). Si pudiera
// tipear un monto, seria justo el agujero que v8/v9 costo cerrar.
//
// Por eso su correccion pasa por EL MISMO chequeo determinístico que el borrador
// del compositor: se extraen los numeros del texto corregido y se comparan contra
// los montos autorizados. Si mete uno que no esta, la correccion se DESCARTA entera
// (no se envia ni la corregida ni la original: se rechaza el turno). El
// verificador reescribe la prosa, nunca la plata.
const corregidoRaw = String(out.mensajeCorregido || '').trim();
let correccionAplicada = false;
let correccionRechazada = false;
let montosDeLaCorreccion = [];
let ofertasBorradas = [];

if (corregidoRaw && corregidoRaw !== String(d.borrador || '').trim()) {
  // MISMA regex que usa Prompt Verificador sobre el borrador: si divergen, el
  // guard mide una cosa distinta de la que audita.
  const enCorreccion = (corregidoRaw.match(/\$\s?[\d.]+/g) || [])
    .map((s) => Number(s.replace(/[^\d]/g, '')))
    .filter((n) => Number.isFinite(n) && n > 0);
  const autorizados = new Set((d.montosAutorizados || []).map(Number));
  montosDeLaCorreccion = enCorreccion.filter((n) => !autorizados.has(n));

  // ═══ GUARD DE OFERTA BORRADA (Martin, 2026-07-29) ═══
  //
  // El verificador borro la promo de inmobiliarias ($15.000 llevando 6) de un
  // mensaje que la traia bien, clasificandola como "informacion innecesaria". El
  // cliente se fue con el precio del suelto y sin saber que existia un precio
  // mejor. El prompt ahora se lo prohibe explicito, pero un prompt no alcanza:
  // no fallo por no saber la regla, fallo JUZGANDO relevancia — y con la regla
  // escrita puede volver a decidir que en ese caso no aplica. El verificador es
  // el ultimo eslabon: nadie lo audita despues de esto.
  //
  // SE COMPARA EL MONTO, NO EL TEXTO. Buscar la frase literal romperia en cuanto
  // reformule, y reformular es justo lo que se le autorizo. Un monto es un
  // numero: o esta o no esta. Misma tecnica que el guard de plata de arriba.
  //
  // DEGRADACION DISTINTA a la del monto inventado: aca NO se rechaza el turno.
  // El borrador original tenia la oferta y era correcto, asi que sale ese. Tirar
  // el turno a mail seria castigar al cliente por un error del auditor.
  const montosOferta = (d.hechos || [])
    .filter((h) => h && h.ofertaBajoMinimo && Number.isFinite(Number(h.monto)))
    .map((h) => Number(h.monto));
  ofertasBorradas = montosOferta.filter((n) => !enCorreccion.includes(n));

  if (montosDeLaCorreccion.length) {
    // el verificador invento un numero al corregir: se tira la correccion Y se
    // rechaza el turno. No se cae a la original en silencio — que el auditor
    // haya tipeado plata es una senal que hay que ver en el log.
    correccionRechazada = true;
    montoInventado = true;
  } else if (ofertasBorradas.length) {
    // borro una oferta: se descarta la correccion y sale el borrador original.
    correccionRechazada = true;
  } else {
    correccionAplicada = true;
  }
}

// EL CHEQUEO DE MONTOS ES DETERMINISTICO Y MANDA EN LAS DOS DIRECCIONES.
//
// Ya mandaba para RECHAZAR (un monto no autorizado tumba un OK del LLM). Faltaba
// la direccion inversa: si el codigo comparo numero por numero y NINGUNO esta
// fuera de la lista, el LLM NO puede alegar 'precio_inventado' — no es una
// opinion, es un hecho ya verificado.
//
// Bug del 2026-07-29 (2do rechazo): el verificador rechazo $88 y $120 diciendo
// que no estaban "en la base cruda", porque el prompt le mostraba solo
// precio_lista y no la escalera de donde salen. El chequeo automatico decia OK
// y el LLM lo contradijo igual. Se arreglo el prompt (ahora ve la escalera) y
// se agrega este piso: el veredicto del codigo sobre PLATA no se discute.
let vetoInvalido = false;
if (!montoInventado && /precio_inventado/.test(fallaLLM)) {
  vetoInvalido = true;
  fallaLLM = '';  // el rechazo por plata se descarta: el codigo ya dijo que no hubo
}

// El rechazo sobrevive solo si NO era por plata (producto equivocado, no
// contesta, dato inventado son juicios legitimos del LLM sobre el texto).
const rechazoLLM = !aprobadoLLM && !vetoInvalido;
const aprobado = !montoInventado && !rechazoLLM;

const falla = montoInventado ? 'precio_inventado'
  : (aprobado ? 'ninguna' : (fallaLLM || 'otra'));

// El sobre que sale de aca es el que leen Log Turno y Log Escalacion, asi que
// tiene que traer TODAS las columnas que esos dos mapean. Si falta una, el
// INSERT escribe null; y si la columna es NOT NULL el INSERT REBOTA ENTERO y,
// con onError:continueRegularOutput, falla EN SILENCIO — cero filas y ninguna
// senal de que algo anda mal. Es exactamente el bug del 2026-07-28 (Log Turno
// escribia null en `accion`), que dejo sin datos todo el trabajo de ese dia.
const productoResuelto = (d.hechos || []).map((h) => h.producto).join(' | ')
  || (d.elegidos || []).map((c) => c.producto).join(' | ')
  || null;

// ¿SE REINTENTA? (decision de Martin 2026-07-29: un rebote al compositor y basta)
//
// Tres condiciones, y las tres tienen que darse:
//
//  1. Es la PRIMERA vuelta. `intento` viene de $runIndex del compositor, que lo
//     lleva n8n — no de un contador nuestro que se pueda desincronizar.
//
//  2. NO fue por plata. `montoInventado` significa que el codigo encontro un
//     numero que el calculo no produjo. Reescribir la prosa no arregla eso: los
//     montos autorizados son IDENTICOS en la segunda vuelta (Calcular Montos no
//     se re-ejecuta), asi que el reintento solo gastaria dos llamadas mas para
//     llegar al mismo rechazo. Va derecho a mail.
//
//  3. Hay algo concreto que corregir. Si el auditor rechazo sin decir por que,
//     el compositor no tiene con que trabajar y el reintento es una moneda al
//     aire con la plata del cliente en el medio.
const intento = Number(d.intento) || 1;
const hayFeedback = String(out.motivo || '').trim().length > 0
  || String(out.queFalta || '').trim().length > 0;
const puedeReintentar = !aprobado && intento < 2 && !montoInventado && hayFeedback;

// por que NO se reintenta, para poder auditarlo desde bot.decisiones
const motivoNoReintento = (aprobado || puedeReintentar) ? null
  : (intento >= 2 ? 'ya_reintento'
    : montoInventado ? 'plata_no_es_reintentable'
    : 'sin_feedback_accionable');

return [{ json: {
  ...d,
  aprobado,
  aprobadoLLM,
  montoInventado,
  // el LLM quiso rechazar por plata cuando el codigo ya habia dicho que no
  // habia monto inventado. Se registra para vigilar si pasa seguido: seria
  // sintoma de que el prompt del verificador sigue mostrando mal la evidencia.
  vetoInvalido,
  falla,
  intento,
  puedeReintentar,
  motivoNoReintento,
  motivoVerificador: String(out.motivo || ''),
  // Log Escalacion mapea `.motivo`: se emite con ese nombre tambien.
  motivo: String(out.motivo || '') || ('v10 falla=' + falla),
  queFalta: String(out.queFalta || ''),
  // lo que sale al cliente: la correccion del verificador si la hubo y paso el
  // guard de plata, si no el borrador del compositor.
  final: aprobado ? (correccionAplicada ? corregidoRaw : d.borrador) : '',
  correccionAplicada,
  correccionRechazada,
  mensajeCorregido: correccionAplicada ? corregidoRaw : '',
  queCorregi: String(out.queCorregi || ''),
  accion: aprobado ? 'respuesta_verificada' : 'handoff',
  notas: 'v10-agents falla=' + falla + ' idxInv=' + (d.idxInvalidos || 0)
    + ' intento=' + intento
    + (puedeReintentar ? ' REINTENTA' : '')
    + (motivoNoReintento ? ' no-reintenta=' + motivoNoReintento : '')
    + (intento > 1 && aprobado ? ' RESCATADO-POR-REINTENTO' : '')
    + (correccionAplicada ? ' CORREGIDO-POR-VERIFICADOR(' + String(out.queCorregi || '?').slice(0, 120) + ')' : '')
    + (montosDeLaCorreccion.length ? ' CORRECCION-CON-PLATA-INVENTADA(' + montosDeLaCorreccion.join(',') + ')' : '')
    + (ofertasBorradas.length ? ' CORRECCION-BORRO-OFERTA(' + ofertasBorradas.join(',') + ')' : '')
    + (d.feedbackPrevio ? ' feedback1=' + String(d.feedbackPrevio).slice(0, 160) : '')
    + (vetoInvalido ? ' VETO-INVALIDO(el LLM alego precio_inventado con chequeo OK)' : ''),
  // columnas que Log Turno espera y que la cadena de agentes no producia
  productoResuelto,
  filasSql: Number(d.nFilas) || 0,
  senales: {
    intencion: d.intencion || null,
    confianzaIntencion: d.confianzaIntencion || 0,
    nCandidatos: (d.candidatos || []).length,
    nElegidos: (d.elegidos || []).length,
    nHechos: (d.hechos || []).length,
    idxInvalidos: d.idxInvalidos || 0,
    dudaNicho: !!d.dudaNicho,
    montoInventado,
    aprobadoLLM,
    vetoInvalido,
    falla,
    intento,
    puedeReintentar,
    motivoNoReintento,
    // el reintento salvo un turno que antes moria en mail
    rescatadoPorReintento: intento > 1 && aprobado,
    // el verificador edito el mensaje en vez de rechazarlo
    correccionAplicada,
    // el verificador tipeo un monto que el calculo no produjo: vigilar
    correccionRechazada,
    // el verificador borro una oferta por cantidad al corregir. Si aparece
    // seguido, el parrafo del prompt no esta alcanzando.
    ofertasBorradas: ofertasBorradas.length,
  },
} }];

// Rearma el prompt del compositor sumandole el feedback del auditor. Los HECHOS
// son los mismos de la primera vuelta (salen de Calcular Montos, que no se
// re-ejecuta): lo unico que cambia es que ahora sabe que fallo.
const v = $('Leer Verificador').first().json;
const base = $('Calcular Montos').first().json;

const queFalta = String(v.queFalta || '').trim();
const motivo = String(v.motivoVerificador || v.motivo || '').trim();

return [{ json: {
  ...base,
  intento: 2,
  feedbackPrevio: (motivo + (queFalta ? ' · ' + queFalta : '')).slice(0, 600),
  borradorRechazado: String(v.borrador || ''),
  fallaPrevia: String(v.falla || ''),
  promptAgente: [
    String(base.promptAgente || ''),
    '',
    '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
    'SEGUNDO INTENTO — TU MENSAJE ANTERIOR FUE RECHAZADO POR EL AUDITOR.',
    '',
    'Lo que escribiste antes:',
    '"""', String(v.borrador || ''), '"""',
    '',
    'Por que lo rechazo:',
    motivo || '(sin motivo)',
    queFalta ? '' : null,
    queFalta ? 'Que falta corregir:' : null,
    queFalta || null,
    '',
    'Reescribi el mensaje corrigiendo ESO. Los HECHOS AUTORIZADOS de arriba no',
    'cambiaron: son los mismos montos y no se tocan. Si el auditor dijo que el',
    'mensaje no contestaba lo que el cliente pregunto, contestalo derecho.',
    'Es tu ultima oportunidad: si vuelve a fallar, el cliente termina en un mail.',
  ].filter((l) => l !== null).join('\n'),
} }];

// EL LOG NO PUEDE DECIR QUE SE CONTESTO SI NO SE CONTESTO.
//
// Caso real (2026-07-29): Chatwoot devolvio "Service temporarily unavailable" y
// el cliente nunca recibio la respuesta. Con onError:continueRegularOutput el
// flujo siguio como si todo hubiera salido bien y Log Turno escribio el mensaje
// en `final`, o sea que la base afirmaba una entrega que no ocurrio. Martin lo
// descubrio mirando WhatsApp, no el log — y tuvo que reenviar a mano.
//
// Un log que miente es peor que el error que oculta: es lo que usas para saber
// si el bot esta funcionando.
//
// COMO SE SABE SI LLEGO: Chatwoot devuelve el mensaje creado con su `id`
// numerico. Si no hay id, no se creo nada. Se chequea eso y no el status HTTP,
// porque con onError el nodo puede emitir un item de error sin status alguno.
const env = $('Leer Verificador').first().json;
const r = $input.first().json || {};

// el id puede venir en la raiz o anidado segun como responda Chatwoot
const idMensaje = r.id || (r.data && r.data.id) || null;
const huboError = !!(r.error || r.errorMessage || r.message === 'Service temporarily unavailable');
const entregado = !!idMensaje && !huboError;

// que fue lo que fallo, para poder verlo en el log sin abrir la ejecucion
const detalle = entregado ? null : String(
  r.errorMessage || (r.error && (r.error.message || r.error)) || r.message
  || 'Chatwoot no devolvio id de mensaje'
).slice(0, 300);

return [{ json: {
  ...env,
  entregado,
  idMensajeChatwoot: idMensaje || null,
  // Log Turno lee estos dos: si no se entrego, `final` NO se escribe como
  // respuesta enviada — se marca el fallo. Asi una consulta por turnos
  // contestados no cuenta los que se perdieron.
  accion: entregado ? env.accion : 'envio_fallido',
  notas: String(env.notas || '') + (entregado ? '' : ' ENVIO-FALLIDO(' + detalle + ')'),
  senales: { ...(env.senales || {}), entregado, envioFallido: !entregado },
} }];
